// HasPartner applies the HasEdge predicate on the "partner" edge.
func HasPartner() predicate.PartnerShippingPreset {
	return predicate.PartnerShippingPreset(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PartnerTable, PartnerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPartnerWith applies the HasEdge predicate on the "partner" edge with a given conditions (other predicates).
func HasPartnerWith(preds ...predicate.Partner) predicate.PartnerShippingPreset {
	return predicate.PartnerShippingPreset(func(s *sql.Selector) {
		step := newPartnerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PartnerShippingPreset) predicate.PartnerShippingPreset {
	return predicate.PartnerShippingPreset(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PartnerShippingPreset) predicate.PartnerShippingPreset {
	return predicate.PartnerShippingPreset(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PartnerShippingPreset) predicate.PartnerShippingPreset {
	return predicate.PartnerShippingPreset(sql.NotPredicates(p))
}
